  "chk.standing.closed.word": "종료됨",
  "chk.standing.closedUnchecked.sentence": "이 실행은 사유가 기록된 채 검사 없이 종료됐어요. 아직 남은 일은 없어요.",
  "chk.standing.closedUnchecked.word": "검사 없이 종료됨",
  "chk.standing.inspecting.sentence": "이 실행은 작업이 끝났다고 말했고 사무실이 검사를 진행하고 있어요. 아직 진행 중인 실행이에요. 작업 트리는 유지되고 이 상태가 이어지는 동안 아무것도 제거되지 않아요. 하위 에이전트가 끝났다고 말해도 이 실행은 끝나지 않아요.",
  "chk.standing.inspecting.word": "검사 중",
  "chk.standing.rebuttal.sentence": "검사가 이 실행을 내보내지 않았고, 이를 위해 열린 그룹에서 논의하는 동안 거부가 유지돼요. 실행은 여기서 끝나지 않아요. 두 가지 중 하나로 끝나요. 작업자가 빠진 부분을 고치고 다시 작업이 끝났다고 말하면 다시 검사로 돌아가고, 그룹이 문제가 없다고 합의하면 누군가가 실행을 내보내요.",
  "chk.standing.rebuttal.word": "거부됨, 논의 중",
  "chk.standing.reporting.sentence": "검사가 이 실행을 내보냈고 보고서가 확인을 기다리고 있어요. 기다리는 동안 실행은 열린 채로 남고 작업 트리를 제거하는 것은 없어요.",
  "chk.standing.reporting.word": "보고서 확인 대기 중",
  "chk.standing.superseded.sentence": "나중 실행이 이 실행의 작업을 끝냈어요. 같은 브랜치에 있었거나, 검사와 병합을 거쳐 이 실행의 커밋을 가지고 있어요. 이 실행은 그 실행에 의해 대체되어 종료됐어요. 봉인, 보고서, 거부, 해제는 그대로이고 아직 남은 일은 없어요. 나중 실행을 읽으면 돼요.",
  "chk.standing.superseded.word": "대체됨",
  "chk.standing.working.sentence": "이 실행은 아직 작업이 끝났다고 말하지 않았으므로 검사할 것이 없어요.",
  "chk.standing.working.word": "작업 중",
  "chk.standingNoCheck.closed.sentence": "이 실행은 확인됐고 끝났어요. 검사가 내보낸 것이 아니에요. 이 프로젝트는 검사자를 요청하지 않았으므로 사무실 규정에 따라 이 작업을 읽은 것은 없어요. 확인이 증명하는 것은 어떤 작업이 수락됐는지, 봉인을 명시했다면 어디인지, 누가 수락했는지예요.",
  "chk.standingNoCheck.closed.word": "종료됨, 검사 없음",
  "chk.standingNoCheck.inspecting.sentence": "이 실행은 작업이 끝났다고 말했어요. 이 프로젝트는 검사자를 요청하지 않았으므로 사무실은 검사를 시작하지 않았고 사무실 규정에 따라 이 실행을 읽은 것은 없어요. 아직 진행 중인 실행이고 검사가 아니라 비서를 기다려요. 작업은 늘 그렇듯 봉인되고 봉인은 아무도 막지 않아요.",
