  "deadLetterRouting.summary.aStarter": "Mole Office는 {addressee}의 시작자 체인에서 연락이 닿은 첫 번째 사람인 {reached}에게 라우팅했어요. 그때 {reached}에게 라우팅한 모든 편지를 나열한 메시지 하나로 {reached}에게 알렸어요.",
  "deadLetterRouting.summary.couldNotTell": "Mole Office는 {addressee}의 시작자 체인에서 연락 불가로 알려지지 않은 첫 번째 사람인 {reached}에게 라우팅했어요. 그때 {reached}에게 라우팅한 모든 편지를 나열한 메시지 하나로 {reached}에게 알렸어요. Mole Office는 {reached}가 응답 중인지 알 수 없었어요.",
  "deadLetterRouting.summary.secretaryInsteadOfTheOwner": "{because}, 그래서 Mole Office는 {owner}가 아니라 데드 레터를 받도록 지정된 비서인 {reached}에게 라우팅했어요. 그때 {reached}에게 라우팅한 모든 편지를 나열한 메시지 하나로 {reached}에게 알렸어요.",
