  "devWords.said.answeringRun": "이 에이전트의 실행이 진행 중이에요. 아무도 이 에이전트를 터미널에서 열어 두지 않았어요.",
  "devWords.said.answeringRunInASandbox": "이 에이전트의 실행이 샌드박스 {sandbox}에서 진행 중이에요. 아무도 이 에이전트를 터미널에서 열어 두지 않았어요.",
  "devWords.said.answeringRunTheOffice": "Mole Office가 시작한 실행이 답하고 있어요. 아무도 이 에이전트를 터미널에서 열어 두지 않았어요.",
  "devWords.said.answeringWaitingRun": "이 에이전트를 위해 시작된 실행이 답하고 {until}까지 다음 메시지를 기다려요. 그때까지 에이전트가 같은 도구를 계속 쓴다면 이 에이전트로 온 메시지는 그 실행의 대화에서 답할 수 있어요.",
  "devWords.said.answeringWaitingRunTheOffice": "Mole Office가 이 에이전트를 위해 시작한 실행이 답하고 {until}까지 다음 메시지를 기다려요. 그때까지 에이전트가 같은 도구를 계속 쓴다면 이 에이전트로 온 메시지는 그 실행의 대화에서 답할 수 있어요.",
  "devWords.said.castingNoRowInForce": "캐스팅 표에 {role}에 적용 중인 행이 없어요.",
  "devWords.said.castingRowForAnotherProgram": "캐스팅 행 {row}은(는) Codex가 아니라 {program}용이에요.",
  "devWords.said.castingRowNoEffort": "캐스팅 행 {row}에 추론 강도가 없어요.",
  "devWords.said.castingRowNoModel": "캐스팅 행 {row}에 모델이 지정되어 있지 않아요.",
  "devWords.said.castingRowNoNativeModel": "캐스팅 행 {row}에 네이티브 모델이 없어요.",
  "devWords.said.castingRowNoProgram": "캐스팅 행 {row}에 프로그램이 지정되어 있지 않아요.",
  "devWords.said.databaseDeleted": "이 서버가 제공 중인 데이터베이스가 {path}에서 삭제됐어요. SQLite는 파일을 디스크립터로 잡고 있어서, 이 프로세스는 삭제된 파일을 계속 읽고 쓰며 응답은 완전히 정상처럼 보여요. 초기화해도 초기화되지 않고, 기록을 쓰면 짧게 읽혀요. 이 서버를 프로세스 그룹 단위로 중지하고 다시 시작하세요. 삭제 이후 여기서 쓴 것은 다른 곳에서 보이지 않아요.",
  "devWords.said.databaseReplaced": "이제 {path}에 다른 데이터베이스 파일이 있어요. 이 서버가 실행 중일 때 교체됐어요. 아마 npm run db:reset 때문일 거예요. 이 프로세스는 여전히 디스크립터로 예전 파일을 제공하고 있어서, 이 프로세스와 그 이후 시작된 것은 모든 기록에서 서로 달라요. 이 서버를 프로세스 그룹 단위로 중지하고 다시 시작하세요.",
  "devWords.said.databaseUnreadable": "Mole Office가 {path}를 열 때 읽지 못했어요. 그래서 제공 중인 파일이 디스크의 파일과 같은지 알 수 없어요.",
  "devWords.said.effortCastingModelDiffers": "캐스팅 행이 다른 모델 {model}을(를) 지정하므로 그 추론 강도은 {asked}에 적용되지 않아요.",
  "devWords.said.effortFromAgent": "실행의 추론 강도는 에이전트 자체 기록에서 온 {effort}예요.",
  "devWords.said.effortFromAgentInPlaceOfTheRow": "실행은 캐스팅 행 {row}의 추론 강도({rowEffort}) 대신 에이전트 자체 기록의 추론 강도({effort})를 받아요.",
  "devWords.said.effortFromCasting": "실행의 추론 강도는 {role}의 캐스팅 행에서 온 {effort}예요.",
  "devWords.said.effortFromCastingRoll": "이 실행은 에이전트의 캐스팅 추첨이 고른 캐스팅 행 {row}에서 추론 강도({effort})를 받아요.",
  "devWords.said.effortFromRule": "실행의 추론 강도는 소유자의 규칙에서 온 {effort}예요.",
  "devWords.said.effortFromTheNamedRow": "실행은 모델 이름 {name}이 지정하는 유효한 유일한 행인 캐스팅 행 {row}에서 추론 강도({effort})를 받아요.",
  "devWords.said.effortNoBuilder": "빌더를 시작하는 어떤 것도 추론 강도을 넘기지 않아요.",
  "devWords.said.effortNoCheck": "검사 도구는 추론 강도을 넘기지 않아요.",
  "devWords.said.effortNoModel": "소유자가 이름 없는 모델에 대해 추론 강도을 설정하지 않았어요.",
  "devWords.said.effortNoneForModel": "소유자가 {model}에 대해 추론 강도을 설정하지 않았어요.",
  "devWords.said.effortOpencodeOnly": "사무실은 메시지에 답할 때 opencode에만 추론 강도을 넘겨요.",
  "devWords.said.effortTheRunIsRefused": "실행이 거부되어 추론 강도이 설정되지 않아요.",
  "devWords.said.effortWithTheModel": "위의 모델과 함께 선택돼요.",
  "devWords.said.modelCodexFillInTheRow": "캐스팅 페이지에서 {role}의 Codex 행을 네이티브 모델과 추론 강도으로 채우세요.",
  "devWords.said.modelCodexNeedsItsRow": "{agent}의 메시지에 응답하는 Codex 실행에 모델을 지정하는 항목이 없어서, {role}에 적용 중인 캐스팅 행을 사용해요.",
  "devWords.said.modelCodexNoCard": "{agent}의 메시지에 답하는 Codex 실행에 모델을 지정하는 것이 없고, 그 역할은 캐스팅 페이지에 카드가 없어요.",
  "devWords.said.modelCodexTakesTheAgentsRow": "메시지에 답하는 Codex 실행은 답하는 에이전트의 캐스팅 행에서 모델을 가져오므로, 여기서는 아무것도 지정하지 않아요.",
  "devWords.said.modelNameMatchesRowsOfDifferentModels": "모델 이름 {name}이 다른 모델을 지정하는 캐스팅 행과 일치해요: {rows}. 어떤 행도 선택이나 추론 강도을 제공하지 않아요.",
  "devWords.said.modelNamedByCaller": "호출자가 모델 {model}을(를) 지정해요.",
  "devWords.said.modelNoneSoNoBuilder": "이 실행에 지정된 모델이 없어서 시작하지 않았어요. 캐스팅 페이지에서 역할 카드에 모델을 지정하거나, 에이전트 프로필에 모델을 설정하세요.",
  "devWords.said.modelNoneSoNoCheck": "이 검사에 지정된 모델이 없어서 시작하지 않았어요. 캐스팅 페이지에서 검사관 카드에 모델을 지정하거나, 검사하는 에이전트의 프로필에 모델을 설정하세요.",
  "devWords.said.modelNoneSoNoConversation": "이 실행에 지정된 모델이 없어서 시작하지 않았어요. 설정 페이지에서 메시지에 답하는 실행에 모델을 지정하거나, 에이전트 프로필에 모델을 설정하세요.",
  "devWords.said.modelNotPassed": "사무실은 메시지에 답할 때 {runtime}에 모델을 넘기지 않아서, {runtime}이 자체 설정을 사용해요.",
  "devWords.said.modelNothingOnTheCasting": "캐스팅 표에서 이 실행이 사용할 수 있는 모델을 지정하지 않았으므로 사무실 런타임 제어가 결정해요.",
  "devWords.said.modelNothingOnTheSettingsPage": "설정 페이지에서 이 실행에 모델을 지정하지 않아서, 사무실 런타임 제어가 결정해요.",
