  "devWords.said.modelOnTheCastingForAnother": "캐스팅 표에서 {its}의 {role}에 대해 {model}을(를) 지정했지만 이 실행은 {this}에 있으므로 사용하지 않아요.",
  "devWords.said.modelOnTheCastingNoProgram": "캐스팅 표에서 {role}에 대해 {model}을(를) 지정했지만 프로그램이 없어서 어떤 프로그램용인지 알 수 없으므로 사용하지 않아요.",
  "devWords.said.modelOnTheSettingsPage": "설정 페이지에서 {where}에 {model}을 지정했어요.",
