  "devWords.said.modelOnlyClaudeCodeBuilders": "캐스팅 표에는 {runtime} 빌더가 사용할 수 있는 모델이 없고, 사무실 런타임 제어는 Claude Code용 모델만 지정해요.",
  "devWords.said.modelTheAgentsOwn": "{model}은 이 에이전트의 프로필에 설정된 자체 모델이에요.",
  "devWords.said.modelTheAgentsOwnEffortDropped": "{model}은 이 에이전트의 프로필에 설정된 자체 모델이에요. 추론 강도({effort})는 이 실행에 넘겨지지 않아요.",
  "devWords.said.modelTheAgentsOwnIsForAnother": "이 에이전트의 자체 모델 {model}은 {its}용이고, 이 실행은 {this}에서 이루어져서 사용되지 않아요.",
