  "devWords.said.priceNotEnoughNumbers": "이 행의 영수증이 가격을 계산할 만큼 충분한 숫자를 제공하지 않았어요.",
  "devWords.said.priceNothingToPrice": "이 행의 어떤 실행도 사용 영수증을 담고 있지 않아서 가격이 추정되지 않아요.",
  "devWords.said.priceUnpricedModel": "가격표에 {model}의 가격이 없어서 가격이 추정되지 않아요.",
  "devWords.said.priceUnpricedRow": "가격표에 이 행이 계산한 어떤 모델의 가격도 없어서 가격이 추정되지 않아요.",
  "devWords.said.profileWorldListUnread": "이 세계에 그 세계의 행이 없어서, 여기에는 데이터베이스 정체성만 있고 이름은 없어요. 사무실의 목록은 읽지 않았어요: {why}",
  "devWords.said.profileWorldMissingFromOffice": "이 세계에도, 사무실이 마지막으로 {at}에 쓴 사무실의 목록에도 그 세계의 행이 없어서, 여기에는 데이터베이스 정체성만 있고 이름은 없어요.",
  "devWords.said.profileWorldNamedByOffice": "이 서버가 보유한 데이터베이스의 명부예요. 그 세계의 이름은 사무실이 마지막으로 {at}에 쓴 사무실의 목록에서 가져와요. 다른 세계는 자기 명부를 따로 가지고 있고, 여기서는 그것을 읽지 않아요.",
  "devWords.said.roundKeepsThePreviousModel": "{project}의 {card}에 유효한 캐스팅 행이 없어서, 라운드는 실행 {run}의 모델 {model}을 유지해요.",
  "devWords.said.roundKeepsTheUnmatchedRun": "{card}에 유효한 캐스팅 행 {row}은 {program}을 지정하며 실행의 프로그램인 {runtime}을 지정하는 유효한 행이 없으므로, 라운드는 실행 {run}의 런타임 {runtime}과 모델 {model}을 유지해요.",
  "devWords.said.roundRowCastsAnotherRuntime": "{card}에 유효한 캐스팅 행 {row}는 {program}을 {model}과 함께 캐스팅하고, 라운드는 실행 {run}을 {runtime}에서 계속하므로 그 행에서 모델을 가져올 수 없어요.",
  "devWords.said.runtimeAddressDiffers": "이 서버는 {api}에서 응답해요. 설정에는 {declared}라고 되어 있는데 다른 주소예요. 그래서 선언된 주소로 찾은 것은 다른 것에 닿았거나 아무것도 닿지 않았어요.",
