  "devWords.said.settingNobodySetTheModel": "{setting}이(가) 설정되지 않았고, 사무실에 기본 모델이 없어요.",
  "devWords.said.settingSaysSo": "{source}에서 {setting}이 그렇게 말해요.",
  "devWords.said.usageNotDeclared": "이 호출은 Mole Office가 적응하는 도구를 선언하지 않은 실행에서 이루어졌어요. 세션 기록에 선언된 도구가 없거나, 세션 기록을 지정하지 않았고 에이전트 레지스트리에 호출자에 대해 적응된 도구가 없어요. 세션 기록이 담고 있는 자유 런타임 단어는 계산되지 않아요. 누구나 거기에 아무 단어나 쓸 수 있기 때문이에요.",
  "devWords.said.usagePatternBloat": "기본 프로젝션이 너무 큰 읽기",
  "devWords.said.usagePatternChain": "id 목록을 받아야 하는 읽기, 또는 이것을 포함해야 하는 컨텍스트 읽기",
  "devWords.said.usagePatternGapLacks": "Mole Office에 복구에 필요한 무언가가 없어요",
  "devWords.said.usagePatternGapUnfound": "Mole Office에 이 작업을 위한 연산이 있는데 아무도 찾지 못했어요",
  "devWords.said.usagePatternPolling": "무언가가 폴링 중인데 아무것도 변하지 않아요",
  "devWords.said.usagePatternRefused": "에이전트가 계속 이것을 틀려요. 형태나 그 문장이 오해를 불러요",
  "devWords.said.usageRefused400": "요청을 사용할 수 없었어요. 필드가 빠졌거나, 철자가 틀렸거나, 형태가 잘못됐어요",
  "devWords.said.usageRefused401": "호출자가 자신이 누구인지 말하지 않았어요",
  "devWords.said.usageRefused403": "호출자가 그렇게 할 수 없어요",
  "devWords.said.usageRefused404": "거기에 아무것도 없어요",
  "devWords.said.usageRefused405": "그 주소는 그 메서드를 받지 않아요",
  "devWords.said.usageRefused409": "무언가가 이미 변경되어서, 쓰기가 덮어쓰지 않고 거부됐어요",
  "devWords.said.usageRefused413": "보낸 것이 너무 컸어요",
  "devWords.said.usageRefused422": "형태는 맞았지만 의미가 틀렸어요",
  "devWords.said.usageRefused429": "한 번에 너무 많아요",
  "devWords.said.usageRefusedOther": "{status}로 거부됐고, 여기에는 아직 그에 대한 설명이 없어요",
  "devWords.said.workerCannotStartAProcess": "메시지 작업자가 시작되지 않았어요. 이 머신 리더는 프로세스를 시작할 수 없어요. 에이전트로 가는 메시지는 대기열에 남아요.",
  "devWords.said.workerDidNotStart": "메시지 작업자가 시작되지 않았어요: {because} 에이전트로 가는 메시지는 대기열에 남고 해당 행에도 그렇게 표시돼요.",
  "devWords.said.workerLastRun": "{handle}, {state}, {at}에 시작",
  "devWords.said.workerNothingTried": "이 서버는 메시지 작업자를 시작하지 않았어요. 아무것도 시도하지 않았어요. API가 작업자를 시작하는 시작 경로 없이 빌드됐어요. 앱을 프로그램으로 실행하지 않고 제자리에서 빌드할 때 그렇게 돼요.",
  "devWords.said.workerOff": "MOLE_OFFICE_MESSAGE_WORKER=off로 메시지 전달이 비활성화됐어요. 에이전트로 가는 메시지는 대기열에 남아요.",
  "devWords.said.workerRunGoing": "{runtime}의 {handle}, {at}에 시작",
  "devWords.said.workerRunWaitOver": "{runtime}의 {handle}, 응답했고 대기가 {until}에 끝났어요. 아직 닫힌 것이 없어요",
  "devWords.said.workerRunWaiting": { other: "{runtime}의 {handle}, 응답했고 다음 메시지를 {n}분 더 기다려요. {until}까지" },
  "devWords.said.workerStarted": "프로세스 {pid}(그룹 {group})로 시작됐고, {log}에 기록해요",
  "devWords.said.workerUnderATestRunner": "메시지 작업자가 시작되지 않았어요. 이 서버가 테스트 러너 아래에서 실행 중이기 때문이에요. 에이전트로 가는 메시지는 대기열에 남고 해당 행에도 그렇게 표시돼요.",
  "devWords.said.worldsTestRunnerReadsNoMirror": "이 서버는 테스트 러너가 시작했고, 선언이 가리키는 사무실은 사람이 사용 중인 사무실이에요. 테스트 세계는 자체 데이터베이스에 등록하고, 자체 표에서 답하며, 다른 사람의 목록을 읽지 않아요.",
  "devWords.said.worldsTheMainWorldWrites": "메인 세계가 {file}을 쓰고, 이 세계는 사무실이 나열할 수 있는 세계예요",
