  "g2b.deadline.gap.no-capacity-stated": "창 안의 기간 중 어느 것도 몇 시간인지 말하지 않아서 용량을 알 수 없어요. 0도 아니고 꽉 찬 근무 주도 아니에요",
  "g2b.deadline.gap.no-date": "기한으로 적힌 것이 날짜가 아니어서 셀 기한이 없어요: 늦은 사람도 없고 남은 시간도 없어요. Mole Office는 말로 된 조건이나 다른 기록을 셀 수 있도록 날짜로 바꾸지 않아요",
  "g2b.deadline.gap.no-whole-period-in-window": "센 범위의 기간 중 지금과 기한 사이에 완전히 들어가는 기간이 없어서 이 범위에서 합산할 것이 없었어요. 사흘에 걸쳐 한 달을 세는 것이 흔한 원인이에요; 더 세밀한 범위로 세세요",
  "g2b.deadline.gap.no-work-named": "이 기한과 관련된 작업이 지정되지 않아서 크기를 잴 것도, 배치할 것도, 맞출 것도 없어요. 이는 요청에 빠진 부분이지 작업에 대한 발견 사항이 아니에요",
  "g2b.deadline.gap.nothing-estimated": "관련 작업 중 어느 것도 소요 시간 추정치가 없어서 이 기한이 얼마나 큰지 아무도 추정하지 않았어요. 0시간도 아니고 작은 일도 아니에요 — 아무도 들여다보지 않은 거예요",
  "g2b.deadline.gap.periods-overlap-the-window": "센 범위의 기간 하나 이상이 이 창과 겹치지만 완전히 안에 들어가지는 않아요. 이름이 나열되고 세지도 않고 크기를 줄이지도 않아요: 기간이 시간을 어떻게 가지는지 아무것도 기록하지 않아서 일부를 나누면 아무도 쓰지 않은 숫자가 돼요",
  "g2b.deadline.gap.plan-at-another-horizon": "이 작업은 세는 기준과 다른 지평에서 기간 안에 배분이 있어요. 그리고 그것은 더하지 않아요. 일주일에 8시간, 월요일에 3시간 계획하면 8시간이지 11시간이 아니에요. 그래서 여기서 계획 합계가 0이어도 다른 곳에 계획되어 있을 수 있어요",
  "g2b.deadline.gap.plan-in-a-clipped-period": "이 작업은 기간이 일부만 덮는 기간(보통 오늘이 속한 주나 달)에 세는 지평으로 계획되어 있어요. 그리고 그 시간은 더하지 않아요. 기간 중 어느 부분에 시간이 있는지 기록이 없기 때문이에요. 그래서 계획 합계는 하한이고 배치되지 않은 합계는 상한이에요",
  "g2b.deadline.gap.some-allocations-without-hours": "이 작업을 가리키는 배분 중 일부는 얼마나 걸리는지 적혀 있지 않아요. 그래서 계획 합계는 적혀 있는 것만 세요. 시간 추정으로 채우지 않아요. 그러면 작업 하나가 오후 하나에 다 들어가 버려요",
  "g2b.deadline.gap.some-periods-without-capacity": "기간 중 일부는 몇 시간인지 적혀 있고 일부는 적혀 있지 않아요. 그래서 여기 용량은 지금부터 마감까지의 일부 시간만 포함해요",
