  "g2b.deadline.standing.waiting-on-a-condition": "글로 적힌 조건이 참이 되면 마감이 돼요. Mole Office는 그것을 확인할 수 없어서 늦은 것이 아니라 대기 중이에요. 조건이 실제로 참이 되면 마감 날짜를 적어 주세요. Mole Office가 만들어 내지 않아요",
