  "g2b.impl.recipients.leftOut": "요청한 한도를 넘어 제외된 최근 연결되지 않은 실행: {count}.",
  "g2b.impl.refused.observed_write": "Mole Office는 git을 실행하지 않아요. 테스트가 그렇게 유지하죠. 대신 중요한 질문에는 정확해요. source_file_hashes의 두 빌드를 비교하면 어떤 파일이 바뀌었는지 정확히 알 수 있어요. 하지만 쓰기를 관찰한다고 해서 관계가 생기지는 않아요. \"에이전트가 Perception을 한다고 말하는 동안 이 파일들이 바뀌었다\"는 상관관계일 뿐이에요. 생산자는 작성되고 내보내지고 변경 기록이 남는 테이블을 기계 행으로 채우게 되는데, 그게 바로 파일 인덱스가 `records`에서 배제되는 이유인 홍수예요.",
  "g2b.impl.refused.structure": "구조 리졸버는 이렇게 말할 거예요. 이 모듈은 Perception이고 이 디렉터리는 perception/이므로 모듈이 디렉터리를 소유한다. A.3은 \"Do NOT assume:\" 다음에 \"Module = directory\"를 열고, L은 \"reduce Module to directory\"를 실패 모드로 지목해요. 값은 선언됐고 생산자는 만들어지지 않았어요. 다시 여는 조건: 디렉터리 이름이 실제로 모듈 이름인 저장소에서 같은 진술을 수십 번 입력하는 경우.",
  "g2b.impl.refusedWord": "거부됨",
