  "g6a.sessions.theReleaseActionForSoNoReleaseButton": "\"{value1}\"의 해제 작업이 {value2}이라서 해제 버튼이 표시되지 않아요. Mole Office가 전체를 명시할 수 없는 작업은 제공하지 않아요.",
  "g6a.sessions.theReplyHasNoOrphansKeyNothingIs": "응답에 `orphans` 키가 없어요. 남겨진 실행 중인 것으로 표시되지 않으며, 이는 남겨진 실행 중인 것이 없다는 것과 같지 않아요 — “이 머신에서 실행 중” 목록이 응답하지 않았어요.",
