  "g6a.sessions.theServerDidNotListWhatElseDied": "서버가 함께 종료된 다른 항목을 나열하지 않았어요. 다른 영향이 없다고 가정하기 전에 머신을 확인하세요.",
  "g6a.sessions.theServerDidNotSayExactlyWhatKilling": "서버가 이 작업을 중단하면 정확히 무엇에 작용하는지 말하지 않아서 버튼이 없어요. Mole Office는 설명할 수 없는 해제를 제공하지 않아요. 직접 중단한 뒤 실제로 해제되었는지 확인하세요.",
