  "g6a.sessions.theSweepReadThisMachineAndFoundNothing": "정리 작업이 이 머신을 읽었고, 활성 원장 행이 소유하지 않은 실행 중 항목을 찾지 못했어요.",
  "g6a.sessions.theTimeWrittenOnTheRecord": " — 기록에 적힌 시각",
  "g6a.sessions.theUnclaimedBlockIsNotAnObjectSo": "`unclaimed` 블록이 {value1}인데 객체가 아니어서 어떤 세션도 주장하지 않는 실행 중인 것에 대해 말할 수 없어요.",
  "g6a.sessions.theUnclaimedSweepCarriesNoSummarySoThe": "`unclaimed` 스윕에 `summary`가 없어서 서버의 설명 문장이 빠졌어요. 아래 행은 여전히 표시돼요.",
