  "gates.count.why.at-the-runs-end": "이 검사는 실행이 끝날 때, 호스트가 실행의 출력 읽기를 멈춘 뒤에 실행돼요. 그래서 이 행은 집계되지 않아요.",
  "gates.count.why.from-inside": "이 검사는 샌드박스 안에서 에이전트 자체 명령으로 시작할 때도 실행되는데, 호스트는 그 출력을 절대 읽지 않아요. 안에서 인쇄된 줄은 샌드박스 자체의 말일 뿐이므로 이 행은 세지 않아요.",
