  "gates.outside.envFile": "적용 중인 위치는 사무실 밖 .env에서 설정됐어요. 사무실은 누가 왜 설정했는지 기록이 없어요.",
  "gates.outside.environment": "적용 중인 위치는 사무실 밖, 사무실이 시작될 때의 환경에서 설정됐어요. 사무실은 누가 왜 설정했는지 기록이 없어요.",
