  "lists.order.findings": "탐색 중인 방향이 먼저 오고, 그다음 측정된 주장이 와요. 각 목록에서 가장 최근에 변경된 기록이 먼저예요. 처음 {n}개의 주장이 표시되고, 목록 아래의 버튼을 누르면 나머지가 보여요.",
  "lists.order.ideas": "활성 아이디어가 먼저, 그다음 보류된 아이디어, 그다음 시도할 것, 그다음 반대하기로 결정한 아이디어가 와요. 각 목록에서 가장 최근에 올린 것이 먼저예요. 목록은 처음 {n}개를 보여주고, 아래의 버튼을 누르면 나머지가 보여요.",
  "lists.order.modules": "모듈은 표시된 상태별로 묶여요: 작업 중, 의도적으로 내려놓음, 지금은 충분함, 사용하지 않음. 그다음 아무도 표시하지 않은 모듈, 그다음 Mole Office가 모르는 단어로 표시된 모듈이 와요. 각 그룹 안에서는 제목 순서예요. 체크된 개수는 페이지를 읽을 때마다 각 모듈의 체크리스트에서 계산해요.",
  "lists.order.pipelines": "필요한 작업은 주의 목록에 있는 단계를 나열해요: 먼저 사람이 다칠 수 있다고 기록한 단계, 그다음 서버가 준 점수 순서로요. 막힌 단계는 사람이 다칠 수 있다고 기록할 때만 거기에 나와요. 막힌 단계가 누구를 기다리는지 기록이 없기 때문이에요. 파이프라인은 각각이 서 있는 단계로 묶여요: 첫 번째 실패한 단계, 없으면 첫 번째 막힌 단계, 없으면 첫 번째 진행 중인 단계, 없으면 첫 번째 시작되지 않은 단계요. 각 그룹에서 먼저 사람이 다칠 수 있다고 기록한 단계를 가진 파이프라인이 오고, 그다음 주의 목록에 있는 단계 수, 그다음 서버가 그중 하나에 준 최고 점수, 그다음 실패한 단계 수 순서예요. 막힌 단계는 마지막 세 가지에 포함되지 않아요.",
