  "mainSuiteTrace.alone": "버전 2 영수증에서 반환된 모든 파일은 단독으로 빨간색이어야 해요. 아무것도 쓰지 않았어요.",
  "mainSuiteTrace.badHandBack": "영수증, 고유 파일, 그리고 두 실행의 커밋, 종료 코드, 로그를 지정하세요. 아무것도 쓰지 않았어요.",
  "mainSuiteTrace.badRange": "절대 저장소 경로와 전체 커밋 해시 두 개를 지정하세요. 아무것도 쓰지 않았어요.",
  "mainSuiteTrace.caller": "원래 전체 스위트 영수증을 제출한 에이전트만, 자신의 에이전트 키로 증명해 반환할 수 있어요. 아무것도 쓰지 않았어요.",
  "mainSuiteTrace.commit": "영수증 커밋은 반영 커밋이거나 main의 이후 커밋이어야 해요. 아무것도 쓰지 않았어요.",
  "mainSuiteTrace.facts": "반영에는 읽을 수 있는 시간과 반영된 커밋이 있어야 해요. 아무것도 쓰지 않았어요.",
  "mainSuiteTrace.files": "반환된 모든 파일은 원래 영수증의 failedFiles에 있어야 해요. 아무것도 쓰지 않았어요.",
  "mainSuiteTrace.green": "반영이 없는 실행은 종료 코드가 0이어야 해요. 아무것도 쓰지 않았어요.",
  "mainSuiteTrace.handBackNote": "메인 스위트 빨간색을 병합된 반영으로 반환해요. 본문 {receipt,files,with:{commit,exit,log},without:{commit,exit,log}}. 원래 영수증 제출자만 자신의 에이전트 키로 증명해요. mainAfter 빨간색, mainBefore 초록색, 이 저장소의 원래 영수증이 반영 커밋 또는 main의 이후 커밋에 있음, 모든 파일이 failedFiles에 있음, 버전 2는 단독 빨간색, 열린 라운드가 필요해요. 반영의 반환 문제와 handedBack 알림을 mainSuiteTrace로 기록하거나, 기존 열린 문제와 unnamedFiles를 지정해요. 거부 시 아무것도 쓰지 않아요.",
  "mainSuiteTrace.merged": "병합된 항목만 메인 스위트 반환을 받을 수 있어요. 아무것도 쓰지 않았어요.",
  "mainSuiteTrace.noRepository": "사무실에 이 저장소의 병합 항목이 없어요. 아무것도 쓰지 않았어요.",
  "mainSuiteTrace.rangeAncestry": "범위는 main에서 끝 커밋의 조상에서 시작해야 해요. 아무것도 쓰지 않았어요.",
  "mainSuiteTrace.rangeCommit": "이 범위의 커밋이 저장소에 없거나 루트를 읽을 수 없어요. 아무것도 쓰지 않았어요.",
  "mainSuiteTrace.rangeLimit": "반영 범위가 200개 커밋을 넘어요. 아무것도 쓰지 않았어요.",
  "mainSuiteTrace.rangeNote": "두 커밋 사이의 병합된 반영. repository=<절대 루트>&from=<전체 해시>&to=<전체 해시>로 질의하세요. 해당 반영 커밋에서 한 저장소의 항목을 순서대로 읽고 id, title, run, line, mainBefore, mainAfter, landedAt과 함께 타일링과 모든 미포함 구간을 보고해요. pushes에는 커밋이 범위에 있는 각 긴급 푸시를 id, mainBefore, commit, 변경한 파일과 함께 나열해요. 알 수 없는 저장소, 읽을 수 없는 커밋, 조상이 아닌 범위, 200개 초과 커밋은 거부해요. 아무것도 쓰지 않아요.",
  "mainSuiteTrace.receipt": "사무실에서 읽을 수 있는 원래 전체 스위트 영수증이 아니에요. 아무것도 쓰지 않았어요.",
  "mainSuiteTrace.red": "반영이 포함된 실행은 종료 코드가 0이 아니어야 해요. 아무것도 쓰지 않았어요.",
  "mainSuiteTrace.repository": "영수증은 병합된 항목의 git 저장소를 지정해야 해요. 아무것도 쓰지 않았어요.",
