  "mergeQueueMeasures.from.bounced": "그날 제출자에게 반송된 항목, 각 반송이 기록한 원인별로 집계.",
  "mergeQueueMeasures.from.fixRounds": "빨간 테스트로 기다리는 항목을 위해 사무실이 연 수정 라운드, 각각 연 날짜로 집계, 변경 로그에서 읽음, 사무실이 라운드가 열린 순간을 기록. 라운드가 열린 후 반송된 항목도 집계. 시작자가 이미 진행 중이던 라운드는 사무실이 연 것이 아니므로 집계하지 않음.",
  "mergeQueueMeasures.from.handBacks": "그날 착륙한 항목 중 몇 개의 테스트 파일이 빨간색이어서 그 줄에 열린 라운드로 반환된 것.",
  "mergeQueueMeasures.from.judgedToLanded": "그날 착륙한 항목에 대해, 각 검사자의 판정에서 착륙까지의 분, 두 순간 사이로 측정. 중앙값과 90번째 백분위수.",
  "mergeQueueMeasures.from.landed": "병합 대기열이 착륙시킨 항목, 각각 착륙한 순간의 날짜로 집계.",
  "mergeQueueMeasures.from.mainRed": "추정치. 영수증으로 main이 빨간색이었던 시간. main은 영수증이 빨간 커밋의 착륙부터 다음 영수증까지 빨간색으로, 영수증이 초록인 커밋의 착륙부터 초록으로 집계. 어떤 항목도 착륙시키지 않은 커밋의 영수증은 실행이 끝난 순간부터 집계. 첫 영수증 전은 아무도 몰라요.",
  "mergeQueueMeasures.from.receipts": "main의 전체 스위트 실행 영수증, 각각 실행이 끝난 날짜에 나열, 빨간색이었던 파일과 함께.",
  "mergeQueueMeasures.from.stable": "안정 사무실이 실행하는 커밋, 지금 체크아웃에서 읽음, 개발 체크아웃의 main과 비교.",
  "mergeQueueMeasures.from.stableAtDayEnd": "그날 끝에 안정 사무실이 실행한 커밋, 업그레이드 공지에서 읽음: 완료된 업그레이드는 새 커밋을 라이브로 했고, 거부되거나 복원된 업그레이드는 이전 커밋을 남겼어요. 그날 끝의 main은 마지막 착륙이 만든 커밋. 안정 사무실에 없던 main의 커밋은 개발 체크아웃에서 git으로 집계.",
  "mergeQueueMeasures.from.submittedToLanded": "그날 착륙한 항목에 대해, 각 제출에서 착륙까지의 분, 두 순간 사이로 측정. 중앙값과 90번째 백분위수.",
