  "mergeQueueMeasures.from.tested": "그날 테스트된 항목, 각각 마지막 테스트가 선택한 방식: 관련 테스트만, 또는 요청한 케이스와 함께 전체 스위트. 항목은 마지막 테스트만 유지해요.",
