  "mergeQueueMeasures.notGiven.testRuns": "각 테스트 실행이 테스트를 어떻게 골랐는지는 주어지지 않아요. 항목은 마지막 테스트만 보관하므로 같은 항목의 이전 실행은 세지 않아요.",
  "mergeQueueMeasures.note": "병합 대기열의 지난 며칠간 측정치. 쿼리 days=<1~30>, 지정하지 않으면 7. 사무실 시간대에서 하루씩, 오늘이 마지막, 각 날의 시작과 끝 시각과 함께 답해요. 각 날마다: 착륙한 항목; 제출에서 착륙까지, 판정에서 착륙까지 대기의 중앙값과 90번째 백분위수; 그날 테스트된 항목이 어떻게 테스트됐는지; 변경 로그에서 사무실이 연 수정 라운드인 반환, 원인별 되돌림과 반송; main의 전체 스위트 영수증과 빨간 파일; 그 영수증으로 main이 빨간색이었던 시간; 그리고 업그레이드 공지에서 그날 끝에 안정 사무실이 실행한 커밋과 그때 main이 얼마나 앞서 있었는지. 또한 지금 읽은 안정 사무실 대 main. 각 수치의 출처, 추정치인지, 제공하지 않는 것을 말해요. 아무것도 쓰지 않아요.",
