  "move.authorityReadContract": "원본 중지 권한을 예약하지 않고 확인해요. 첫 핸드오프는 기존 {scope, authority, sendId, expectedBefore?} 요청을 받아요. 데이터 폴더 이동은 {scope: DataFolderMoveStopScope, decision: StableNoticeOriginal, sendId: string}를 받거나, {action: stop-to-move-the-data-folder, targetFolder: absolute path}로 원본 결정을 하나 발견해요. 대상은 기본값이 없어요. 응답은 범위와 생성 핀을 반향하고, available/reserved/consumed를 제공하며, 호출자와 예약 시작자를 식별해요. GET /api/kinds는 두 중지 범위를 게시해요.",
  "move.authorityReserveContract": "데이터 폴더 이동을 위해 원본 소유자 결정을 하나 예약해요. 키가 지정된 시작 실행이 {scope: DataFolderMoveStopScope, decision: StableNoticeOriginal, sendId: string}를 보내요. 모든 필드는 원본 생성 범위와 일치해야 해요. 두 번째 예약은 거부돼요. 정산된 결과는 {reservation: StableNoticeOriginal, outcome: moved|restored|not-restored|refused}를 추가하고 같은 시작 실행에 대한 예약을 소비해요. 이는 원본 노트를 작성하며 업그레이드 알림을 보내지 않아요.",
  "move.backupHashDiffers": "데이터베이스 전용 백업 해시가 승인된 해시와 달라요.",
  "move.backupMissing": "승인된 데이터베이스 전용 백업이 없어요.",
  "move.consumed": "데이터 폴더 이동이 정산된 결과를 기록했어요.",
