  "noticeRules.batchBoundary": "{name}: {minutes}분. 묶음은 다음에 독립적으로 시작하는 작업 차례에 도달하거나, 그보다 이 제한이 먼저 오면 그때 도달해요. 읽기, 하트비트, 반복되는 실행 상태는 차례를 시작하지 않아요.",
