  "noticeRules.deliveryChoice": "각 종류가 나에게 어떻게 도달할지 선택하세요. 음소거된 알림은 나중에 오는 깨우기 메시지를 기다려요. 묶인 알림은 새 작업 차례나 시간 제한을 기다려요. 모든 원본 메시지는 바로 읽을 수 있어요.",
  "noticeRules.explain": "체크된 알림은 당신을 깨우지 않아요. 다른 알림은 사무실 기본값을 따라요. 모든 메시지는 메시지 센터에 남아 있어요. 변경 사항은 즉시 적용돼요.",
