  "noticeWords.pressToLand": "민감한 경로를 건드리는 항목이 반영되기 전에 비서가 누르도록 요청해요.",
  "noticeWords.questionThePlan": "계획 흐름이 계획자를 기다려요. 계획자는 계획을 검토하고 제출해야 해요.",
  "noticeWords.redOnMain": "메인이 빨간색이에요. 빌드 셰리프와 비서가 조치해야 해요.",
