  "noticeWords.released": "작업자에게 해제됐고 끝내도 된다고 알려요.",
  "noticeWords.releasedAndTheStarterIsTold": "작업자에게 해제됐다고 알려요. 동시에 실행을 제출하는 시작자에게도 알려요. 작업자는 할 일이 없어요.",
  "noticeWords.releasedToOneThatReadsTheCheck": "검사 자체에서 이미 해제를 읽었다고 말한 에이전트에게 해제를 알려요. 거부되면 여전히 깨워요.",
  "noticeWords.removedFromYourChecklist": "다른 사람이 그 사람의 체크리스트에서 항목을 제거했다고 알려요.",
  "noticeWords.resourcesLeftOpen": "실행이 끝났는데 무언가를 붙잡고 있어요. 상사가 그것을 놓아야 해요.",
  "noticeWords.stableUpgradeNotice": "업그레이드 공지나 결과를 기록하고 아무것도 묻지 않아요.",
  "noticeWords.storageCapacity": "대상 용량 알림은 나중에 읽을 수 있도록 보관되며, 바로 할 일은 없어요.",
  "noticeWords.takeBackNeedsAPerson": "기한이 지난 반환은 사람이 먼저 살펴봐야 되돌릴 수 있어요.",
  "noticeWords.takenBack": "기한이 지난 반환이 초록색 병합 항목에 의해 되돌려졌어요.",
  "noticeWords.territoriesInConflict": "실행 중인 두 실행의 영역이 겹쳐서 그 라인들이 해결해야 해요.",
  "noticeWords.theBroadcastIsDue": "비서에게 기한이 된 보고서를 쓰라고 요청해요.",
