  "noticeWords.theBroadcastsArePaused": "보고서가 일시 중지되었다고 알려요.",
  "noticeWords.theCapStoppedForYou": "에이전트에게 다시 시작하라고 글을 쓰도록 사람에게 요청해요.",
  "noticeWords.theCheckEnded": "검사가 판정과 함께 끝났다고 알려요. 판정 자체가 깨우는 메시지예요.",
  "noticeWords.theCheckFailed": "검사가 판정 없이 실패했고 사무실이 자동 반복을 대기열에 넣지 않았어요. 누군가 다시 시작해야 해요.",
