  "noticeWords.theCheckStarted": "검사가 시작됐다고 알려요.",
  "noticeWords.theExpectedTimeHasArrived": "실행이 예상 시간에 도달했고 답장은 필요 없다고 알려요.",
  "noticeWords.theGovernsCheckFoundWork": "지정된 비서에게 governs 검사가 나열한 결정에 대해 조치하도록 요청해요. 밤에 최대 한 번이에요.",
  "noticeWords.theIntentMarkWasBroken": "그 사람이 답장이 자신의 표시를 깨뜨렸다고 말했어요. 이는 에이전트에게 아무것도 바꾸지 말거나 아직 만들지 말라고 요청한 것이에요.",
  "noticeWords.theLoginsWeekIsPartUsed": "샌드박스의 Claude 로그인이 7일 중 50% 또는 80%를 사용했어요. 80%에서는 비서에게 소유자에게 남은 7일을 물어보라고 알려요.",
  "noticeWords.theOfficeLoadIsOutOfRange": "사무실 자체 수치 중 하나가 범위를 벗어나서 비서가 살펴봐야 해요.",
  "noticeWords.theOverlapEnded": "청구의 중복이 끝났다고 말해요. 그래서 해결할 것이 남지 않았어요.",
  "noticeWords.thePersonMarkedAnItemDone": "소유자가 이 에이전트가 추가했거나 알림 대상으로 지정된 항목을 완료로 표시했고, 작업이 그 항목을 기다렸을 수 있어요.",
  "noticeWords.theRunsAStopCauseStopped": "한 가지 원인으로 실행이 중지되었고, 그 사람이 조치해야 해요.",
  "noticeWords.tooManyInTheMainWorld": "메인 세계에 실행이 너무 많아서 시작한 사람이 조치해야 해요.",
  "noticeWords.twiceTheExpectedTime": "실행이 예상 시간의 두 배를 넘겨서 감독자에게 알리라고 요청해요.",
  "noticeWords.workAreasInConflict": "두 작업 영역이 중복되고, 두 보유자가 해결해야 해요.",
