  "noticeWords.youHaveBeenIdle": "유휴 에이전트에게 임무를 상기시켜요. 일부러 기다리는 에이전트는 할 일이 없어요.",
  "noticeWords.youHoldACard": "에이전트에게 역할과 임무를 읽도록 건네요.",
  "noticeWords.yourRaiseEnded": "승격이 끝났다고 알려요.",
  "officeLines.backAsTheSecretarySetIt.line": "비서가 설정한 대로 돌아왔어요",
  "officeLines.backAsTheSecretarySetIt.said": "비서가 당신의 권한으로 이 알림을 설정했어요. 이 알림은 그 하나예요.",
  "officeLines.backAsYouAsked.line": "요청하신 대로 돌아왔어요",
  "officeLines.backAsYouAsked.said": "이 메시지에서 '나중에 알림'을 누르셨어요. 이 알림은 그 하나예요.",
  "officeLines.branched.line": "다른 대화에서 분기됨",
  "officeLines.branched.said": "이 대화는 {name}(\"{handle}\")에게 연락할 수 없어서 열렸으며, 그 에이전트와의 대화에서 시작해요. 그 대화는 온전히 보관되어 있고 여전히 거기에 있어요. 아무것도 옮겨지지 않았고 삭제되지도 않았어요. {name}이 돌아오면 거기서 기다리는 것에 답할 거예요.",
  "officeLines.intentMarkBroken.line": "그 사람이 당신의 답변이 자신의 표시를 깨뜨렸다고 말했어요",
  "officeLines.intentMarkBroken.said": "그 사람이 자신의 메시지 {message}에 대한 당신의 답변 {reply}에 \"표시 깨짐\"을 눌렀어요. 그 사람의 표시는 이렇게 말했어요: {asks} Mole Office는 메시지, 표시, 당신의 답변을 지목하는 문제 {problem}을 접수했어요.",
  "officeLines.intentMarkBrokenForThePerson.line": "비서가 그 사람을 대신해, 당신의 답변이 그 사람의 표시를 깨뜨렸다고 말했어요",
  "officeLines.intentMarkBrokenForThePerson.said": "비서 \"{secretary}\"가 그 사람의 권한으로, 그 사람의 메시지 {message}에 대한 당신의 답변 {reply}에 \"깨짐 표시\"를 눌렀어요. 그 사람의 표시는 이렇게 말했어요: {asks} Mole Office는 문제 {problem}을 접수했고, 여기에는 메시지, 표시, 당신의 답변이 명시되어 있어요.",
  "officeLines.restart.line": "Mole Office가 다시 시작되었어요",
  "officeLines.restart.said": "이 에이전트가 답변하던 중에 Mole Office가 다시 시작되어, 실행이 아무 말도 하지 못하고 중지되었어요. 작성하신 내용은 하나도 잃지 않았어요. 답변이 필요하면 메시지를 다시 보내세요.",
  "officeLines.youHoldACard": "당신이 {card} 카드를 가지고 있어요",
  "officePause.explain": "일시 중지하면 메시지 작업자가 멈추고, 사무실에서 시작한 실행에 일시 중지를 요청해요. 페이지는 계속 동작해요. 다시 시작하면 이 사무실 일시 중지가 끝나요. 일시 중지된 실행은 평소처럼 누르기를 기다려요.",
  "officePause.loading": "사무실 일시 중지 상태",
  "officePause.open": "일시 중지 제어 열기",
  "officePause.paused": "{who}가 {when}부터 일시 중지함. 이유: {because}",
