  "queueRelated.alone": "관련 항목만 검사는 정확한 항목 트리에서 테스트돼요",
  "queueRelated.case1": "사례 1: 병합 도구 자체 코드가 바뀌어서 전체 스위트가 이후 항목의 테스트 방식을 검사해요{rest}.",
  "queueRelated.case2": "사례 2: 마이그레이션이나 데이터베이스 경로가 바뀌어서 전체 스위트가 사무실 전반에서 쓰는 데이터를 검사해요{rest}.",
  "queueRelated.case3": "사례 3: 안정적인 업그레이드 도구가 바뀌어서 전체 스위트가 실행 중인 사무실을 업그레이드하는 경로를 검사해요{rest}.",
  "queueRelated.case4": "사례 4: 서버 시작이나 감독자가 바뀌어서 전체 스위트가 서버와 작업자가 함께 시작하는 방식을 검사해요{rest}.",
  "queueRelated.case5": "사례 5: 관련 목록을 만들 수 없었어요. {reason}",
  "queueRelated.case6": "사례 6: 관련 목록이 전체 테스트 파일의 절반을 넘거나 모든 테스트 파일이에요. {reason}",
  "queueRelated.case7": "사례 7: npm test가 셸에 스크립트와 모든 파일 이름을 하나의 인자로 넘기는데, 관련 테스트 파일 {files}개면 최대 {bytes}바이트가 되어 Linux가 허용하는 {most}바이트를 넘어요. 그래서 전체 스위트를 실행하고, 길이를 줄이려고 테스트를 빼지 않아요.",
  "queueRelated.coverage": "이 항목은 전체 스위트를 실행하지 않았어요. 다음 메인 스위트가 이를 검사하고, 수정 라운드는 적용되지 않았어요.",
  "queueRelated.green": "빌드와 관련 테스트 {files}개가 실제로 반영되는 트리에서 통과했어요.",
  "queueRelated.halfEvery": "변경 {range}은(는) 전체 테스트 파일 {every}개 모두에 닿아요(전체 트리 목록에서 관련 파일 {related}개). 그래서 병합 대기열이 전체 스위트를 실행해야 해요.",
  "queueRelated.halfNeedsPrint": "--at-most-half에는 --list related와 --print가 필요해요. 아무것도 실행되지 않았어요.",
  "queueRelated.halfOver": "변경 {range}은(는) 전체 트리 목록에서 관련 테스트 파일 {related}개를 지정해요. 전체 테스트 파일 {every}개의 절반({most})을 넘어서 병합 대기열이 전체 스위트를 실행해야 해요.",
  "queueRelated.invalid": "관련 테스트만 선택하는 위치 {value}은(는) 허용되지 않아요. 0 또는 1이어야 해서 아무것도 테스트하지 않았어요.",
  "queueRelated.morePaths": ", 나열된 스무 개 경로 외에 {count}개 경로가 더 있어요",
  "queueRelated.noFacts": "run-named-tests가 읽을 수 있는 선택 정보를 주지 않았어요: {reason}",
  "queueRelated.noPathList": "경로 사례가 전체 스위트를 요구해서 관련 항목만 선택할 때 쓸 관련 목록을 만들지 않았어요.",
  "queueRelated.noSlowBound": "사무실에 관련 테스트 우선 설정이 없어요(404). 그래서 느린 테스트 기준 시간이 null이고, 느리다는 이유로 빠진 파일은 없어요.",
  "queueRelated.redCoverage": "이 항목에 대해 전체 스위트가 실행되지 않았고 수정 라운드도 적용되지 않았어요.",
