  "review.pane.yourReview": "내 검토",
  "review.pane.yourReviews": "내 검토",
  "review.scopeGap.aDraft": "이 검토는 초안에서 시작됐어요. 초안은 브라우저에만 보관되어서 서버에 모을 것이 없어요.",
  "review.scopeGap.aPage": "이 검토는 포인터 아래에 더 정확한 것이 없는 페이지에서 시작됐어요. 그래서 아무도 말하지 않은 채 프로젝트 전체를 모으게 돼요. 프로젝트 전체 검토를 요청하거나, 먼저 페이지의 무언가를 가리키세요.",
  "review.scopeGap.anAction": "이 검토는 읽기 안의 동작에서 시작됐어요. Mole Office는 그런 동작을 따로 보관하지 않아서 모을 것이 없어요.",
  "review.scopeGap.checklist": { other: "여기 기록 하나에 체크리스트 항목 {n}개가 있어요. 체크리스트 항목은 기록이 아니라서 여기에 나열할 수 없어요. 기록을 열어서 보세요." },
  "review.scopeGap.loop": "여기 기록들이 서로의 일부로 순환 저장되어 있어서 Mole Office가 거기서 세기를 멈췄어요. 이 검토에서 빠진 기록이 있을 수 있어요.",
  "review.scopeGap.namedTwice": "여기 파이프라인 순서의 {position}번 자리가 {first}번 자리와 같은 기록을 가리켜요. 한 번만 세요.",
  "review.scopeGap.namesNoRecord": "이 검토가 시작된 대상이 기록을 가리키지 않아서 모을 것이 없어요.",
  "review.scopeGap.noConversation": "이 검토가 시작된 대화가 더 이상 저장되어 있지 않아서, Mole Office가 무엇을 모으는지 알 수 없어요.",
  "review.scopeGap.noMessage": "이 검토가 시작된 메시지가 더 이상 저장되어 있지 않아서, Mole Office가 어떤 대화를 모으는지 알 수 없어요.",
  "review.scopeGap.notAnId": "여기 파이프라인 순서의 {position}번 자리에 기록이 없어서 아무것도 셀 수 없어요.",
  "review.scopeGap.notHanded": "Mole Office가 여기 기록 하나를 읽을 수 없어서 거기서 세기를 멈췄어요. 이 검토에서 빠진 기록이 있을 수 있어요.",
  "review.scopeGap.otherProject": "이 검토는 다른 프로젝트의 대화에 있는 메시지에서 시작됐어요. 검토는 한 프로젝트의 작업에 대한 것이어서 아무것도 모으지 않아요.",
  "review.scopeGap.partOfTheScreen": "이 검토는 화면의 일부에서 시작됐어요. 그 부분은 모든 페이지에 있어서 검토가 프로젝트 전체가 되어버려요. 프로젝트 전체 검토를 요청하거나, 먼저 페이지의 무언가를 가리키세요.",
  "review.scopeGap.partOfTwo": "여기 기록 하나가 둘 이상의 것에 속해 있어요. 한 번만 나열해요. 기록은 한 가지에만 속해야 해서 누군가 고쳐야 해요.",
  "review.scopeGap.recordDeleted": "이 검토가 시작된 기록이 삭제됐어요. 그래도 이 검토가 모으는 대상이고, 복원되기 전까지는 거기서 새 검토를 시작할 수 없어요.",
  "review.scopeGap.recordGone": "이 검토가 시작된 기록이 더 이상 저장되어 있지 않아요.",
  "review.scopeGap.tooDeep": "여기 기록들이 {n}단계보다 더 깊이 저장되어 있고, Mole Office는 그보다 더 깊이 세지 않아요. 그 아래에 있는 것은 이 검토에 들어 있지 않아요.",
  "review.scopeGap.twoParents": "여기 기록 하나가 서로 다른 두 가지의 일부로 저장되어 있어서 Mole Office가 거기서 세기를 멈췄어요. 이 검토에서 빠진 기록이 있을 수 있어요.",
  "review.scopeSays.conversation": "이 검토가 시작된 대화에서 말한 모든 것.",
  "review.scopeSays.gone": "아래 이유로 Mole Office는 이 검토가 무엇을 모으는지 말할 수 없어요. 그동안 아무것도 여기에 속하지 않으며, 아무것도 추측하지 않았어요.",
  "review.scopeSays.plan": "이 검토가 시작된 계획에 관한 모든 것, 계획의 모든 줄을 포함해요.",
  "review.scopeSays.projectAsked": "이 프로젝트의 모든 것. 누군가 프로젝트 전체 검토를 요청해서, 시작된 위치는 그저 그 사람이 어디에 있었는지를 말해줄 뿐이에요. 검토가 무엇을 모으는지에는 아무 영향도 없어요.",
  "review.scopeSays.projectFromPage": "이 프로젝트의 모든 것. 이 검토는 포인터 아래에 더 정확한 것이 없는 페이지에서 시작되었으므로, 프로젝트가 Mole Office가 정직하게 말할 수 있는 가장 작은 범위예요.",
  "review.scopeSays.record": { other: "“{title}”, 이 검토가 시작된 기록, 그 안의 모든 것, 그리고 보고서의 블록이나 표의 행 또는 셀처럼 그중 어느 것의 일부라도 포함해요. {n}개의 기록이 그 일부로 저장되어 있어요." },
  "review.scopeSays.recordAlone": "“{title}”, 이 검토가 시작된 기록, 그리고 보고서의 블록이나 표의 행 또는 셀처럼 그 일부라도 포함해요. 그 일부로 저장된 것은 없으므로, 이것이 범위의 전부예요.",
  "review.scopeSays.recordMissing": "이 검토가 시작된 기록으로, Mole Office가 더 이상 가지고 있지 않은 기록, 그리고 여전히 그것을 가리키는 모든 것.",
  "review.scopeSays.window": "이 검토가 시작된 주의 블록, 그 외에는 없어요.",
  "review.send.messageTo": { other: "{name}에게: 댓글 {n}개가 담긴 메시지 하나" },
  "review.send.messagesLabel": "에이전트마다 하나의 메시지",
  "review.send.savedWithNobody": "저장된 이 댓글에 아직 아무도 선택되지 않았어요. 그래서 검토를 보내면 이 댓글이 남게 돼요. 해당 행에서 받을 사람을 선택한 다음 검토를 보내세요.",
  "review.vocab.abandon.detail": "이 검토를 끝내요. 더 이상 아무것도 전송되지 않아요.",
  "review.vocab.abandon.word": "포기",
  "review.vocab.cancel.detail": "확인을 실행하지 않고 나가요.",
  "review.vocab.cancel.word": "취소",
  "review.vocab.earlier.detail": "이 검토가 수집을 시작하기 전에 작성됐어요.",
  "review.vocab.earlier.word": "이전",
  "review.vocab.elsewhere.detail": "이 검토가 다루지 않는 내용에 대해 작성됐어요.",
  "review.vocab.elsewhere.word": "다른 곳",
  "review.vocab.finishCollecting.detail": "이 검토에 있는 내용을 기록해요. 아무것도 전송되지 않고, 되돌릴 수 없어요.",
  "review.vocab.finishCollecting.word": "수집 마치기",
  "review.vocab.inAnotherReview.detail": "다른 검토가 이미 수집했어요.",
