  "server.castingNotAProgram": "“{program}”은(는) 사무실이 아는 프로그램이 아니에요. 아무것도 바뀌지 않았어요.",
  "server.castingNotOwnerOrACardThatHoldsIt": "소유자나 캐스팅 표를 바꿀 권한이 있는 카드를 가진 에이전트만 바꿀 수 있어요. 에이전트는 자기 키로 카드를 증명해요. 아무것도 바뀌지 않았어요.",
