  "server.checkAlsoByTheRunItself": "실행 자체의 키로는 실행이 무엇을 알림 받을지 정할 수 없어요. 시작한 사람이나 그 사람이 이 항목을 줘요. 아무것도 바뀌지 않았어요.",
  "server.checkAlsoItemTooLong": "봉인 전 알림 항목은 각각 최대 300자예요. 아무것도 바뀌지 않았어요.",
  "server.checkAlsoNotARun": "봉인 전 알림 항목은 실행에만 붙일 수 있는데, 이 기록은 실행이 아니에요. 아무것도 바뀌지 않았어요.",
  "server.checkAlsoTooMany": "봉인 전 알림 항목은 실행당 최대 20개예요. 아무것도 바뀌지 않았어요.",
  "server.checkAlsoWrittenOutsideItsDoor": "실행의 봉인 전 알림 항목은 실행을 등록할 때 주거나, 나중에 따로 줘야 해요. 실행의 다른 변경과 함께 줄 수 없어요. 아무것도 바뀌지 않았어요.",
  "server.checklistChangedSinceRead": "페이지가 열려 있는 동안 이 체크리스트가 바뀌어서 아무것도 변경하지 않았어요.",
  "server.checklistOwnWordsNeedTheDonePress": "작성된 응답은 항목을 완료로 표시하는 누름과 함께 가요. 같은 변경에서 완료로 표시하세요.",
  "server.checklistOwnWordsNeedTheVersion": "작성된 응답은 당신이 읽은 체크리스트 버전과 함께 가요. 다시 읽고 그 버전을 함께 보내세요.",
  "server.checklistOwnWordsNotTheOwner": "이 체크리스트의 소유자만 항목에 자신의 말을 쓸 수 있고, 완료로 표시하는 누름과 함께만 쓸 수 있어요.",
  "server.chineseHalfNotFromThisEnglish": "이 변경 후에는 이 기록의 중국어 번역이 옆의 영어와 맞지 않게 돼요. 영어와 중국어를 함께 바꾸세요. 아무것도 쓰지 않았어요.",
