  "sheet.aDependencyNobodyRecordedAsALinkIsInvisible": "링크로 기록되지 않은 의존성은 여기서 보이지 않아요. 쿼리는 링크를 읽지, 문장을 읽지 않아요.",
  "sheet.aDirectionHasNoStateFieldAndIsNot": "방향에는 상태 필드가 없고 미완성 기록도 아니에요. 여섯 단계에는 분수만이 아니라 이름이 있어요.",
