  "sheet.aPartialGateIsNotAWeakerHardGate": "부분 게이트는 약한 하드 게이트가 아니에요. 대부분의 작업은 할 수 있지만 끝에 벽이 있다는 답이고, 그 벽이 어디인지 말해줘요.",
  "sheet.aPauseIsADecisionNotAFailureSo": "멈춤은 실패가 아니라 결정이에요. 그래서 이것들 중 어느 것도 주의 목록에 없어요. 각각은 내려놓은 이유와, 있다면 무엇이 다시 가져올지를 간직해요.",
  "sheet.aPersonCouldBeHurtTheScannerArmKeeps": "사람이 다칠 수 있어요: 정지 버튼을 눌러도 스캐너 암이 계속 움직이고, 아카이브 스캔 시험 중에는 누군가 그 옆에 서 있어요",
  "sheet.aRecordDeletedAndReplacedUnderANewTitle": "삭제되고 새 제목으로 대체된 기록은 끊긴 것으로 보여요. 링크가 옮겨지지 않았기 때문이에요.",
  "sheet.aRecordsListIsTheCaseThatMustNot": "기록 목록은 경보로 읽히면 안 되는 경우예요: 아래의 모든 단어는 기록에 저장되어 있고, 어느 것도 결함이 아니에요. 먼저 지각적, 그다음 분석적, 그리고 두 가지가 바뀌어요. 수준이 전혀 없는 단어는 경보 색을 빌리기를 멈춰요. 두 띠에서 유일한 빨강이에요. 그리고 수준을 가진 세 개는 경보 척도의 회색으로 그려지기를 멈추고 같은 전체 텍스트 색을 가져요. 그 회색은 중립 가족의 색조가 섞이는 회색이니까요 — 저장된",
  "sheet.aRowThatScansClosedAndIsCompleteOpen": "닫히면 스캔되고, 열리면 완전한 행",
  "sheet.aRowWithNoStateAtAllTheColumn": "상태가 전혀 없는 행 — 열은 그대로 비워 둬요",
  "sheet.aRuleACaveatADescriptionOfWhatA": "규칙, 주의 사항, 패널이 다루지 않는 범위에 대한 설명은 처음 한 번은 꼼꼼히 읽고 그다음 이백 번의 방문에서는 건너뛰게 돼요. 의미의 한 줄은 계속 보여요. 문장 자체를 줄여서 보여주지, “규칙”이라고 적힌 서류 카드를 보여주는 게 아니에요. 이것은 모든 너비에서 접혀요. 이웃한 StandingNote는 480px 아래에서만 접히고 그보다 넓으면 감싸는 요소를 아예 렌더링하지 않아요. 그러니 책상에서 문장이 그 자리를 값할 만하고 휴대폰에서만 감당하기 어려울 때는 StandingNote를 쓰세요.",
  "sheet.aRunningSessionIsNotAskedToExplainItself": "실행 중인 세션은 그 행에서 스스로를 설명하라고 요구받지 않아요. 접힌 곳 뒤에 있는 것은 출력이 가는 위치이고, 그것은 이유가 아니라 사실이에요.",
  "sheet.aSafetyRowSitsAboveARowScoring103": "안전 행은 103점인 행보다 위에 있어요. 안전은 큰 숫자가 아니라 별도의 정렬 키이기 때문이에요. 이건 숨길 게 아니라 보여 줘야 하는 동작이에요.",
  "sheet.aStateMayCarryANumberInsteadOfIts": "상태는 단어 대신 숫자를 담을 수 있어요.",
  "sheet.aStateWordMeansOneThingEverywhereHowLoudly": "상태 단어는 어디서나 한 가지를 뜻해요. 표면이 그것을 얼마나 크게 그리는지는 표면의 목적에 달려 있어요. 홈은 훑어보는 곳이라 색은 긴급함에 쓰이고 같은 상태의 두 행은 비슷해 보여요. 세션, 기록, 쿼리는 비교하는 곳이라 색은 상태로 돌아가고 수준이 무게를 가져요. surfaceEmphasis()로 표면마다 한 번 선언하고, 행 사다리는 둘 다 같아요.",
  "sheet.aStateWordNobodyHasClassifiedIsNotQuietly": "아무도 분류하지 않은 상태 단어가 조용히 빠지지는 않아요. 그 단어는 물음을 그대로 적은 채 자기 목록으로 돌아와요. “이 단어가 무슨 뜻인지 아무도 말하지 않았다”는 것은 사람에게 할 질문이지, 그 작업에 대한 판정이 아니니까요. 상태 단어가 아예 없는 기록도 마찬가지예요. 그건 또 다른 질문이에요.",
  "sheet.aStateWordThisInterfaceDidNotChoose": "이 인터페이스가 고르지 않은 상태 단어",
  "sheet.aTitleLongEnoughToProveThatWrappingWorks": "페이지 전체를 옆으로 밀지 않고 줄바꿈이 제대로 되는지 보여 줄 만큼 긴 제목이에요. 말줄임만 하는 규칙은 대부분 한 문장인 아카이브 메모를 그냥 잘라 내요.",
  "sheet.aWordNobodyHasClassifiedAQuestionNotA": "아무도 분류하지 않은 단어 — 판정이 아니라 질문",
