  "sheet.alarm.faded": "일주일 넘게 전에 중단됐고 그 뒤로 달라진 게 없어요. 일부러 가장 조용해요 — 오래된 실패가 물러나는 단계이고, 옆의 숫자가 얼마나 오래됐는지 말해줘요.",
  "sheet.alarm.plain": "중단됐고 날짜는 상관없으며, 새것도 오래된 것도 아니에요. 텍스트 색으로 그려져요: 읽을 수 있고, 위의 두 단계와 경쟁하지 않아요.",
  "sheet.alarm.raised": "날짜가 앞으로 이틀 안에 있거나, 지난 이틀 안에 중단됐어요. 레일은 유지하지만 색은 빠져서, 위 단계가 아니라는 게 분명해요.",
  "sheet.alarm.urgent": "누군가 다칠 수 있거나, 누군가 합의한 날짜가 지났어요. 레일이 경보 색으로 그려지는 유일한 단계이고, 행을 채우는 유일한 단계예요 — 안전을 위해서일 뿐, 다른 이유는 없어요. 이 지점을 넘어 커지는 것은 숫자이고 색이 아니에요.",
