  "sheet.bothAreOnThisPageAtOnceSoThey": "둘 다 이 페이지에 함께 있어서 비교할 수 있어요. 위쪽 경고는 내용이 있는데 거짓말하고 있다고 말해요. 아래쪽 블록은 내용이 없으며 그건 허용된다고 말해요. 색도 다르고, 구조도 다르고, 무게도 다르고, 단어도 달라요. 눈을 가늘게 뜨고 보거나 data-theme을 mono로 바꿔도 둘은 여전히 하나로 모이지 않아요.",
