  "sheet.dataPartsIsNotFilledInSoThisModule": "data.parts가 채워지지 않아 이 모듈은 미완성이에요. 진행 체크리스트는 이름 붙은 파트로 묶여요. 아직 체크리스트에 아무것도 없으면 []를 보내세요. 빈 체크리스트도 답이고, 완료로 여겨요. 기록은 어느 쪽이든 남아요. 알게 되면 채워 넣으세요. 예: [{\"id\":\"mount\",\"name\":\"Scanner stand\",\"items\":[]}]",
