  "sheet.elevenStoredWordsDrawnByWhatTheyMean": "저장된 열한 가지 단어, 의미대로 그려요",
  "sheet.emphasis.analytical": "화면은 \"이건 어떤 상태지?\" 하고 물어요. 칩마다 제 상태 색을 그대로 갖고, 경보 수준은 굵기에만 맡겨요. 그래서 여섯 상태가 한눈에 여섯 가지로 읽혀요. 행은 사다리 전체를 그대로 지녀서, 오래된 행은 상태 단어가 회색으로 죽지 않고도 뒤로 물러나요.",
  "sheet.emphasis.perceptual": "화면은 \"무엇이 나를 필요로 할까?\" 하고 물어요. 색은 경보 단계에 쓰고 칩에서는 모두 빼요. 그래서 같은 상태의 두 행은 서로 닮게 보이고, 눈에 띄는 행이 바로 오늘 사람이 필요한 행이에요. 이것이 기본값이고, Home은 이 방식을 위해 설계한 화면이에요.",
  "sheet.emphasisCode.analytical": "분석적",
  "sheet.emphasisCode.perceptual": "지각적",
  "sheet.emptyErrorLoading": "비어 있음, 오류, 로딩 중",
  "sheet.everyRowOnTheAttentionListCarriesItsOwn": "주의 목록의 모든 행에는 저마다 이유가 붙어 있어요. 서버에서 계산해 여기에 그대로 출력해요. 문장은 항상 보이고, 그 뒤의 계산은 버튼 하나면 볼 수 있어요. 아래의 “점수 103 — 계산 과정”을 누르세요. 요인 분석은 검사이고, 순위에 든 요인뿐 아니라 아무 가치도 없는 요인도 보여 줘요.",
  "sheet.everyRowReservesTheSameLeftColumnWhetherOr": "모든 행은 상태가 있든 없든 같은 왼쪽 열을 비워 둬요. 그래서 막힌 작업이 세로줄로 쌓여요. 왼쪽 가장자리를 따라 눈을 내려 보세요. “뭔가 잘못됐나?”에 대한 답이 거기 다 있어요.",
  "sheet.everyWriteRecordsWhoDidItAsANamed": "모든 쓰기는 누가 했는지를 이름이 있는 사람 또는 이름이 있는 에이전트로 기록하고, 그 이름은 추측이 아니라 저장돼요. 작성자가 기록되지 않은 기록은 그렇다고 밝히고, 어느 쪽에도 분류되지 않아요.",
