  "sheet.families.note": "{n}가지 종류는 목록에서 구별하기에 너무 많고, 여섯 계열은 그렇지 않아요. 계열은 제목과 탐색을 위해 종류를 묶을 뿐 그 밖에는 아무것도 하지 않아요. 계열은 단색이고, 컴포넌트는 자기가 어느 계열인지 알려 주는 속성을 내보내지 않아요. 그래서 스타일시트가 붙잡아 색을 줄 수 있는 것이 없어요. 색은 상태에 써요.",
