  "sheet.focusTheChipAndPress1ToDo2": "칩에 포커스한 뒤 1을 눌러 할 일, 2를 눌러 하는 중, 3을 눌러 완료, 4를 눌러 실패, 5를 눌러 차단됨으로 바꿔요. Enter 또는 Down을 누르면 메뉴가 열리고, 화살표로 이동하며, Escape를 누르면 닫히고 포커스가 칩으로 돌아가요.",
  "sheet.fourArchiveTasksWaitOnThisScan": "네 개의 아카이브 작업이 이 스캔을 기다려요",
  "sheet.fourChannelsApartABrokenArrowShaftADashed": "네 가지 채널로 구분해요: 끊어진 화살대, 점선 테두리, 다른 색, 그리고 단어 자체",
  "sheet.fourDifferentEmptyMessagesNeverOneNoResultsEmpty": "네 가지 빈 메시지를 각각 보여 주고, “결과 없음” 하나로 처리하지 않아요. 빈 상태는 세 가지 중 어느 것인지 호출자가 말하지 않은 없음이라서 조용히 그려요. 문장은 남고 상자는 사라져요. 로딩 중에는 최종 배치를 유지해서 데이터가 도착해도 화면이 튀지 않아요.",
  "sheet.fourLevelsAndAtMostOneStrongRedObject": "네 단계가 있고, 어떤 행에도 강한 빨강 요소는 많아야 하나예요. 맨 위 단계의 레일만 경보 색으로 그려요. 오래된 실패는 맨 아래 단계로 물러나요. 저장된 단어와 경과 시간은 메타데이터라 모든 단계에서 텍스트 색으로 남아요. 색을 얻게 하는 건 표시, 놓친 날짜, 오류예요.",
