  "sheet.inertTextNoBoxNoUnderlineNoPointer": "반응 없는 텍스트 — 테두리 없음, 밑줄 없음, 포인터 없음.",
  "sheet.inferredLinksAreIncludedAndAreMarkedAsInferred": "추론된 링크도 포함되고 추론됨으로 표시돼요. Mole Office가 알아낸 것이고, 사람이 단언한 것이 아니에요.",
  "sheet.itAskedShouldIKeepTheOldLabelReader": "이렇게 물었어요: “이 배치에 예전 레이블 리더를 계속 쓸까요, 아니면 지금 바꿀까요?” 아무도 답하지 않았어요. 상태 단어는 “idle”로 남아 있고, 여기서 그것만 보고 “당신을 기다리는 중”이라고 추론하지 않아요.",
  "sheet.itStoppedShortThisMorningSoItIsStill": "오늘 아침에 도중에 멈춰서 아직 새 소식이에요",
  "sheet.itsStateWordIsFailedWhichMeansTheWork": "상태 단어는 \"failed\"이고, 이는 작업이 끝나기 전에 멈췄다는 뜻이에요",
  "sheet.itsStateWordIsOpenWhichMeansTheWork": "상태 단어가 \"open\"이라서 작업이 끝까지 가지 못하고 중단됐어요. 기록된 결과: 정지 버튼을 눌러도 스캐너 암이 계속 움직이고, 아카이브 스캔 시험 중에는 누군가 그 옆에 서 있어요",
  "sheet.jammedThePrinter": "프린터가 걸림",
  "sheet.kind": "종류",
  "sheet.knownGaps": "알려진 공백",
  "sheet.labelHintAndErrorAreWiredToTheControl": "레이블, 힌트, 오류는 id로 컨트롤에 연결되어 있어요. 그래서 화면 낭독기가 세 가지를 모두 읽어요. 힌트는 상자 아래가 아니라 물음표 뒤에 있어요. 필드를 아는 사람이 같은 내용을 다시 읽지 않아도 되니까요. 비워 둘 수 있는 필드는 레이블 옆에 그렇다고 표시해요. 접기가 숨기면 안 되는 사실이 바로 그거니까요.",
