  "sheet.mixedScriptAndLongText": "문자가 섞인 긴 텍스트",
  "sheet.moleOfficeCannotTellWhetherTheseStoppedShortBecause": "Mole Office는 이것들이 끝까지 가지 못했는지 알 수 없어요. 이 오래되었거나 가져온 기록의 상태 단어가 무슨 뜻인지 아무도 말하지 않았으니까요.",
  "sheet.moleOfficeDoesNotKnowTheKindTelemetrySo": "Mole Office는 “telemetry”라는 종류를 몰라서, 여기에 상태가 있어야 했는지 말할 수 없어요",
  "sheet.moleOfficeDoesNotKnowTheKindTelemetrySo2": "Mole Office는 종류 “telemetry”를 몰라서 상태가 예상되었는지 말할 수 없어요 — 기록 2개",
  "sheet.moleOfficeShowsUnknownOrIncompleteWhenItCannot": "Mole Office는 더 강한 주장을 뒷받침할 수 없을 때 알 수 없음 또는 불완전으로 표시해요. 조용히 다른 방법으로 바꿔 놓고 그 결과를 성공이라고 하지 않아요.",
  "sheet.mountTheScanner": "스캐너 연결",
  "sheet.navigational": "이동",
  "sheet.newRecord": "새 기록",
  "sheet.noEvidenceLinked": "연결된 증거 없음",
  "sheet.noRecordMatchesPageReader42Loaded": "“page reader”와 일치하는 기록이 없어요. 42개를 불러왔어요.",
  "sheet.noRecordTitled": "“{title}”이라는 기록이 없어요.",
  "sheet.noRecordWrittenThroughTheApiCanLandHere": "이제 API를 통해 작성된 기록은 여기에 들어올 수 없어요. 종류는 자신이 선언하지 않은 단어를 거부하고, 종류가 선언하는 모든 단어는 분류되어 있어요. 남는 것은 고고학이에요 — 자신이 속했던 어휘보다 오래된 기록이거나, 가져오기가 들여온 행이에요.",
  "sheet.noRecordsYetCreateOneToStart": "아직 기록이 없어요. 하나 만들어 시작하세요.",
  "sheet.noState.kindUnknown": "종류를 알 수 없음",
  "sheet.noState.noField": "상태 필드 없음",
  "sheet.noState.noFieldDetail": "이 종류의 기록에는 상태 필드가 없어서 읽을 단어가 없어요. 이는 빈틈이 아니라 답이에요.",
  "sheet.noState.unknownDetail": "Mole Office는 이 종류를 모르기 때문에, 여기에 상태가 있어야 하는지 말할 수 없어요.",
  "sheet.noState.unwritten": "상태가 기록되지 않음",
  "sheet.noState.unwrittenDetail": "이 종류의 기록에는 상태가 있는데 여기에는 아무것도 기록되지 않았어요. 그래서 저장된 상태만으로는 이것이 중간에 멈췄는지 알 수 없어요.",
  "sheet.noStateAtAllThreeDifferentAnswersThreeDifferent": "상태가 전혀 없어요 — 세 가지 다른 답, 세 가지 다른 단어",
  "sheet.noStateHasChangedMeaningAndNoColourHas": ". 어떤 상태도 뜻이 바뀌지 않았고 어떤 색도 새로 만들지 않았어요: 네 가족은 상태 자체의 색조를 되찾고 수준은 무게를 계속 가져요. 두 가족은 그렇지 않아요.",
  "sheet.nobodyHasGivenThisWorkAnEstimate": "이 작업에는 아무도 추정치를 내지 않았어요.",
  "sheet.nobodyHasLookedForProcessesThatNoAgentRun": "어떤 에이전트 실행도 차지하지 않은 프로세스를 아무도 찾아보지 않았어요. 그래서 주인 없는 실행 중으로 표시되는 것은 없어요.",
  "sheet.nobodyHasRecordedWhoIsHurtIfThisIs": "이걸 그대로 두면 누가 피해를 보는지 아무도 기록하지 않았어요",
  "sheet.nobodyHasSaidHowLongThisTakes": "이 작업에 얼마나 걸리는지 아무도 말하지 않았어요.",
  "sheet.nobodyHasSizedAnyOfThisWorkSoThere": "이 작업은 아무도 규모를 산정하지 않았어요. 그래서 규모 열이 없어요.",
  "sheet.nobodyLooked": "아무도 보지 않음",
  "sheet.notTheSameAsNoHours": "{absence} 그건 시간이 없는 것과는 달라요.",
  "sheet.nothingFollowsFromLeavingIt": "그냥 둬도 아무 일도 생기지 않아요",
  "sheet.nothingHereIsStatedByColourTheFilledBlock": "여기서 색으로 말하는 것은 없어요. 채워진 블록은 희소해요: 지금 누군가 당신을 기다리고 있다는 뜻이고, 답을 기다리는 에이전트, 포트를 계속 잡고 있는 실행, 누군가 동의한 날짜를 넘긴 것에 쓰여요.",
  "sheet.nothingHiddenIsStillAnAnswerAndItIs": "숨긴 것이 없다는 것도 여전히 답이에요. 그리고 그건 접기와는 다른 문장이에요. “이게 전부인가요?”라는 질문은 목록의 한 단어도 읽기 전에 답이 나와요.",
  "sheet.nothingRecordedStandsBehindIt": "뒷받침하는 기록이 없어요",
  "sheet.oneColourThreeNumbersEscalationAboveTheTopOf": "색은 하나, 숫자는 셋 — 척도 맨 위를 넘는 단계 상승은 숫자로 나타내요. 경보 색보다 더 센 색은 없으니까요.",
  "sheet.oneComponentTreeDrivenByTokensEnclosedItWrites": "컴포넌트 트리는 하나이고 토큰이 움직여요. 테두리로 감싸면 = 쓰기가 돼요. 평소에 밑줄이 있으면 = 이동해요. 맨 텍스트 = 반응 없음. 모든 상태는 단어와 모양과 색을 함께 쓰고, 색만으로는 표시하지 않아요. 이 시트의 예시는 지어낸 것이에요.",
  "sheet.oneIsStillTheHeavierStrokeAndTheLast": "하나는 여전히 더 굵은 획이고, 마지막 두 단계는 똑같이 그려져요. 계열에 자기 색을 돌려주면 여기와 위쪽 띠의 한 단계가 그렇게 되는 거예요.",
  "sheet.oneStripAndTheExactCountEveryStripIs": "막대 하나와 정확한 개수예요. 모든 막대의 너비가 같아서 길이가 다른 두 실행도 열을 따라 비교할 수 있어요.",
  "sheet.oneTestDecidesTheWeightDoesTheReaderHave": "무게는 한 가지 기준으로 정해져요. 읽는 사람이 이 없음에 대해 뭔가 해야 하나요? 보통의 비어 있음은 흐린 대시로만 표시하고 문장으로 쓰지 않아요. “아무도 보지 않음”과 “없음”은 구분돼야 해요. 그래서 하나는 점선 테두리로 감싸요. 누군가 메울 수 있는 빈틈이니까요. 다른 하나는 아무 테두리도 없어요. 답이니까요. 없음 자체가 발견 사항일 때만 문장을 붙여요.",
