  "sheet.safety.detail": "저장된 결과가 “사람이 다칠 수 있다”인 항목은 점수와 상관없이 안전이 아닌 모든 항목보다 위에 있어요. 시간이 지나도 순위가 밀리지 않아서, 1분 전에 올린 안전 항목도 첫 줄에 와요.",
