  "sheet.saving": "저장 중",
  "sheet.scan.open": "기록 전체 열기",
  "sheet.scanFirstExplainOnDemandClosedARowShows": "먼저 스캔하고, 요청 시 설명해요. 닫히면 행은 스캔에 필요한 네 가지를 보여줘요: 무엇인지, 무엇이 잘못됐는지, 얼마나 큰 소리인지, 얼마나 오래됐는지. 열리면 호출자가 전달한 모든 것을 보여줘요 — 공간을 만들기 위해 삭제되는 것은 없어요. 요약이 곧 컨트롤이라서, 휴대폰에서 아무도 누를 수 없는 캐럿 대신 전체 줄이 대상이에요. 오른쪽 열은 절대 “더 보기”라고 말하지 않아요: 무엇이 열리는지 이름을 붙이고, 개수가 의미 있는 곳에서는 얼마나 되는지 말해요.",
