  "sheet.whatKindOfThingThisIsDrawnByFamily": "이것이 어떤 종류인지 계열별로 그려요. 글리프와 레일로, 모든 종류를 따로 그리지 않고 여섯 계열로 묶어요. Mole Office에 부를 단어가 없는 종류는 정상인 것처럼 넘기지 않고 그렇다고 표시해요.",
